export type PropertyPath = string | number | symbol | (string | number | symbol)[];
export type NestedKeyOf<T extends object> = {
    [K in keyof T & (string | number)]: T[K] extends object ? `${K}` | `${K}.${NestedKeyOf<T[K]>}` : `${K}`;
}[keyof T & (string | number)];
export type ObjectEntry<T> = {
    [K in keyof T]: [K, T[K]];
}[keyof T];
export type ObjectFromEntries<T extends [string, unknown][]> = {
    [K in T[number][0]]: Extract<T[number], [K, unknown]>[1];
};
export type Merge<T, U> = Omit<T, keyof U> & U;
export type DeepMerge<T, U> = {
    [K in keyof T | keyof U]: K extends keyof U ? K extends keyof T ? T[K] extends object ? U[K] extends object ? DeepMerge<T[K], U[K]> : U[K] : U[K] : U[K] : K extends keyof T ? T[K] : never;
};
export type Diff<T, U> = Omit<T, keyof U>;
export type Intersection<T, U> = Pick<T, Extract<keyof T, keyof U>>;
export type RenameKey<T, K extends keyof T, N extends string> = Omit<T, K> & {
    [P in N]: T[K];
};
export type ValueOf<T> = T[keyof T];
export type Entries<T> = [keyof T, T[keyof T]][];
export type FromEntries<T extends [string, unknown][]> = {
    [K in T[number][0]]: Extract<T[number], [K, unknown]>[1];
};
export type InvertObject<T extends Record<string, string>> = {
    [K in T[keyof T]]: {
        [P in keyof T]: T[P] extends K ? P : never;
    }[keyof T];
};
export type FlattenObject<T extends object, P extends string = ''> = {
    [K in keyof T]: T[K] extends object ? FlattenObject<T[K], `${P}${K & string}.`> : {
        [Key in `${P}${K & string}`]: T[K];
    };
}[keyof T];
export type PickNested<T, K extends string> = K extends `${infer F}.${infer R}` ? F extends keyof T ? PickNested<T[F], R> : never : K extends keyof T ? T[K] : never;
